gnedIn=<?= $signedIn?'true':'false' ?>,csrfToken=<?= json_encode(csrfToken()) ?>;let selected=null;document.querySelectorAll('.table-card').forEach(b=>b.onclick=()=>{selected=b;document.getElementById('table-id').value=b.dataset.id;document.querySelectorAll('.table-card').forEach(x=>x.className='table-card rounded-2xl border border-gray-200 bg-white p-5 text-left shadow-sm transition hover:border-brand hover:shadow-md');b.className='table-card rounded-2xl border-2 border-brand bg-brand-light p-5 text-left shadow-sm'});document.getElementById('reservation-form').onsubmit=async e=>{e.preventDefault();let err=document.getElementById('error');if(!selected){err.textContent='Please choose a table.';err.classList.remove('hidden');return}if(!signedIn){location.href='../login.php?return=reservation';return}err.classList.add('hidden');try{let r=await fetch('../../customer-reservation.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),csrf_token:csrfToken})}),o=await r.json();if(!o.success)throw Error(o.error);document.getElementById('code').textContent=o.reservation_code;document.getElementById('success').classList.remove('hidden')}catch(x){err.textContent=x.message||'Could not request reservation.';err.classList.remove('hidden')}};const side=document.getElementById('sidebar'),parts=document.querySelectorAll('.nav-text,.brand-detail');document.getElementById('sidebar-toggle').onclick=()=>{let open=side.classList.toggle('w-[240px]');side.classList.toggle('w-[80px]',!open);parts.forEach(x=>x.classList.toggle('hidden',!open));localStorage.setItem('yhCustomerSidebarOpen',open)};if(localStorage.getItem('yhCustomerSidebarOpen')==='true')document.getElementById('sidebar-toggle').click();else parts.forEach(x=>x.classList.add('hidden'));</script></body></html>
